def _sslc(self):
    if self.protocol != 's':
        return None
    return ssl.SSLContext(ssl.PROTOCOL_TLS)

def _connector(self, session_factory, proxy):
    return connect_rs(
        self.host,
        self.port,
        proxy=proxy,
        session_factory=session_factory,
        ssl=self._sslc()
    )

def electrum_request(method, params, servers=None):
    import socks
    from concurrent.futures import ThreadPoolExecutor, as_completed

    if servers is None:
        servers = SERVERS

    clean_params = [
        p.hex() if isinstance(p, bytes) else p.lower() if isinstance(p, str) else p
        for p in params
    ]

    server_items = list(servers.items())
    random.shuffle(server_items)

    use_tor = (
        os.path.exists("/etc/os-release")
        and "TAILS" in open("/etc/os-release").read().upper()
    )

    tor_proxy = ("127.0.0.1", 9050)

    if not use_tor:
        try:
            with socket.create_connection(tor_proxy, timeout=1):
                use_tor = True
        except Exception:
            pass

    def try_server(item):
        host, info = item
        port = info.get("s")

        if not port:
            return None

        sock = None
        ssock = None
        attempt_start = time.perf_counter()

        try:
            req = {
                "id": 0,
                "method": method,
                "params": clean_params,
            }

            msg = (json.dumps(req) + "\n").encode()

            if use_tor:
                sock = socks.socksocket()
                sock.set_proxy(
                    socks.SOCKS5,
                    tor_proxy[0],
                    tor_proxy[1],
                )
                sock.settimeout(TIMEOUT)
                sock.connect((host, port))
            else:
                sock = socket.create_connection(
                    (host, port),
                    timeout=TIMEOUT,
                )

            context = ssl._create_unverified_context()

            ssock = context.wrap_socket(
                sock,
                server_hostname=host,
            )

def set_status_bar_balance(self, shown: bool) -> None:
    if shown:
        balance = 0
        for account in self._wallet.get_accounts():
            c, u, x = account.get_balance()
            balance += c
        bsv_status, fiat_status = app_state.get_amount_and_units(balance)
    else:
        bsv_status, fiat_status = _("Unknown"), None
    self._status_bar.set_balance_status(bsv_status, fiat_status)
